#!/usr/bin/env python3
"""Security audit for the AndroidManifest generated by Capacitor during CI."""

import sys
import xml.etree.ElementTree as ET
from pathlib import Path

ANDROID = "{http://schemas.android.com/apk/res/android}"

# Empty by design: any dangerous permission requires an explicit reviewed change.
APPROVED_DANGEROUS_PERMISSIONS = set()

DANGEROUS_PERMISSIONS = {
    "android.permission.READ_CALENDAR",
    "android.permission.WRITE_CALENDAR",
    "android.permission.CAMERA",
    "android.permission.READ_CONTACTS",
    "android.permission.WRITE_CONTACTS",
    "android.permission.GET_ACCOUNTS",
    "android.permission.ACCESS_FINE_LOCATION",
    "android.permission.ACCESS_COARSE_LOCATION",
    "android.permission.ACCESS_BACKGROUND_LOCATION",
    "android.permission.RECORD_AUDIO",
    "android.permission.READ_PHONE_STATE",
    "android.permission.READ_PHONE_NUMBERS",
    "android.permission.CALL_PHONE",
    "android.permission.ANSWER_PHONE_CALLS",
    "android.permission.READ_CALL_LOG",
    "android.permission.WRITE_CALL_LOG",
    "android.permission.ADD_VOICEMAIL",
    "android.permission.USE_SIP",
    "android.permission.PROCESS_OUTGOING_CALLS",
    "android.permission.SEND_SMS",
    "android.permission.RECEIVE_SMS",
    "android.permission.READ_SMS",
    "android.permission.RECEIVE_WAP_PUSH",
    "android.permission.RECEIVE_MMS",
    "android.permission.BODY_SENSORS",
    "android.permission.BODY_SENSORS_BACKGROUND",
    "android.permission.ACTIVITY_RECOGNITION",
    "android.permission.READ_EXTERNAL_STORAGE",
    "android.permission.WRITE_EXTERNAL_STORAGE",
    "android.permission.READ_MEDIA_IMAGES",
    "android.permission.READ_MEDIA_VIDEO",
    "android.permission.READ_MEDIA_AUDIO",
    "android.permission.READ_MEDIA_VISUAL_USER_SELECTED",
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.BLUETOOTH_SCAN",
    "android.permission.BLUETOOTH_CONNECT",
    "android.permission.BLUETOOTH_ADVERTISE",
    "android.permission.NEARBY_WIFI_DEVICES",
}

def fail(message: str) -> None:
    print(f"Android manifest security audit FAILED: {message}", file=sys.stderr)
    raise SystemExit(1)

def main() -> None:
    if len(sys.argv) != 2:
        fail("usage: audit-android-manifest.py <AndroidManifest.xml>")

    manifest_path = Path(sys.argv[1])
    if not manifest_path.is_file():
        fail(f"manifest not found: {manifest_path}")

    try:
        root = ET.parse(manifest_path).getroot()
    except ET.ParseError as error:
        fail(f"invalid XML: {error}")

    permissions = {
        node.get(ANDROID + "name", "")
        for node in root.findall("uses-permission")
    }
    sensitive = sorted(permissions & DANGEROUS_PERMISSIONS)
    unapproved = sorted(set(sensitive) - APPROVED_DANGEROUS_PERMISSIONS)
    if unapproved:
        fail("unapproved dangerous permissions: " + ", ".join(unapproved))

    application = root.find("application")
    if application is None:
        fail("application element is missing")

    if application.get(ANDROID + "usesCleartextTraffic", "false").lower() == "true":
        fail("application enables cleartext network traffic")

    component_tags = ("activity", "activity-alias", "service", "receiver", "provider")
    exported = []
    missing_exported = []

    for tag in component_tags:
        for component in application.findall(tag):
            name = component.get(ANDROID + "name", "<unnamed>")
            exported_value = component.get(ANDROID + "exported")
            has_intent_filter = component.find("intent-filter") is not None

            if has_intent_filter and exported_value is None:
                missing_exported.append(f"{tag}:{name}")
                continue

            if exported_value == "true":
                is_launcher = (
                    tag == "activity"
                    and any(
                        action.get(ANDROID + "name") == "android.intent.action.MAIN"
                        for action in component.findall("./intent-filter/action")
                    )
                    and any(
                        category.get(ANDROID + "name") == "android.intent.category.LAUNCHER"
                        for category in component.findall("./intent-filter/category")
                    )
                )
                if not is_launcher:
                    exported.append(f"{tag}:{name}")

    if missing_exported:
        fail("components with intent-filters missing android:exported: " + ", ".join(missing_exported))
    if exported:
        fail("unexpected exported components (only the launcher activity is allowed): " + ", ".join(exported))

    print("Android manifest security audit passed.")
    print(f"Declared permissions reviewed: {len(permissions)}")
    print(f"Approved dangerous permissions: {len(sensitive)}")
    print("Exported components: launcher activity only (or none).")
    print("Cleartext traffic: disabled.")

if __name__ == "__main__":
    main()
